class Solution {
public:
    int minTimeToReach(vector<vector<int>>& moveTime) {
        int n = moveTime.size();
        int m = moveTime[0].size();
        const long long INF = (1LL << 62);
        vector<vector<long long>> dist(n, vector<long long>(m, INF));
        priority_queue<pair<long long, int>> pq;

        dist[0][0] = 0;
        pq.push({0, 0});

        int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (!pq.empty()) {
            pair<long long, int> cur = pq.top();
            pq.pop();
            long long d = -cur.first;
            int idx = cur.second;
            int r = idx / m;
            int c = idx % m;

            if (d != dist[r][c]) continue;
            if (r == n - 1 && c == m - 1) return (int)d;

            for (int k = 0; k < 4; ++k) {
                int nr = r + dirs[k][0];
                int nc = c + dirs[k][1];
                if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;

                long long nd = d;
                if ((long long)moveTime[nr][nc] > nd) nd = moveTime[nr][nc];
                nd += 1;

                if (nd < dist[nr][nc]) {
                    dist[nr][nc] = nd;
                    pq.push({-nd, nr * m + nc});
                }
            }
        }

        return (int)dist[n - 1][m - 1];
    }
};
